import { AbsoluteFill, Audio, Sequence, staticFile } from "remotion";
import { loadFont } from "@remotion/fonts";
import { SceneHost } from "./SceneHost";
import { DOUDOU_SECONDS, SCENES, SCENE_TIMES } from "./timing";

// "Doudou and the Moon": a narrated cut-paper bedtime story, 1920x1080.
// Scenes and timings are generated by doudou-moon/tools/build.py (the same drawings and timelines as
// the HyperFrames version); narration is public/doudou/voice/<scene>.wav from doudou-moon/tools/vo.py.

export const DOUDOU_FPS = 30;
export const DOUDOU_TOTAL_FRAMES = Math.round(DOUDOU_SECONDS * DOUDOU_FPS);

// Bundled under public/doudou/fonts (SIL OFL), so renders never reach Google Fonts.
loadFont({ family: "Nunito", url: staticFile("doudou/fonts/nunito-700-latin.woff2"), weight: "700" });
loadFont({ family: "Nunito", url: staticFile("doudou/fonts/nunito-800-latin.woff2"), weight: "800" });

const f = (s: number) => Math.round(s * DOUDOU_FPS);

export const DoudouMoon: React.FC = () => {
  return (
    <AbsoluteFill style={{ backgroundColor: "#16263a" }}>
      {SCENE_TIMES.map((t, i) => {
        const from = f(t.start);
        const next = i + 1 < SCENE_TIMES.length ? f(SCENE_TIMES[i + 1].start) : DOUDOU_TOTAL_FRAMES;
        return (
          <Sequence key={t.id} name={t.id} from={from} durationInFrames={next - from}>
            <SceneHost scene={SCENES[i]} />
            <Sequence name={`vo ${t.id}`} durationInFrames={Math.ceil(t.voice * DOUDOU_FPS)} layout="none">
              <Audio src={staticFile(`doudou/voice/${t.id}.wav`)} />
            </Sequence>
          </Sequence>
        );
      })}
    </AbsoluteFill>
  );
};
